import{_ as s,a0 as o,w as i,s as r,ao as d,I as a,x as n,a1 as u,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const _=JSON.parse('{"title":"Ubuntu每日小技巧 – 深入理解應用菜單和按鈕 | LCTT x X-CMD","titleTemplate":false,"description":"Ubuntu每日小技巧 – 深入理解應用菜單和按鈕 | LCTT (201310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Ubuntu每日小技巧 – 深入理解應用菜單和按鈕 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Ubuntu每日小技巧 – 深入理解應用菜單和按鈕 | LCTT (201310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201310/Daily Ubuntu Tips – Understanding The App Menus And Buttons","title":"Ubuntu每日小技巧 – 深入理解應用菜單和按鈕","tag":"201310","desc":""},"relativePath":"201310/Daily Ubuntu Tips – Understanding The App Menus And Buttons.md","filePath":"[post].md"}'),l={name:"201310/Daily Ubuntu Tips – Understanding The App Menus And Buttons.md"};function b(T,t,m,g,f,U){const e=o("Link");return i(),r("div",null,[t[11]||(t[11]=d(`<h1 id="ubuntu每日小技巧-–-深入理解應用菜單和按鈕" tabindex="-1">Ubuntu每日小技巧 – 深入理解應用菜單和按鈕 <a class="header-anchor" href="#ubuntu每日小技巧-–-深入理解應用菜單和按鈕" aria-label="Permalink to “Ubuntu每日小技巧 – 深入理解應用菜單和按鈕”">​</a></h1><p>Ubuntu是一款很不錯的操作系統。它基本上可以做到任何現代操作系統能做的事情，甚至有時候能做的更好。如果你是一個ubuntu新手，那麼你現在還有很多不知道的事情。對於那些專家級用户來説十分普通的事情可能對你來説可能就不太普通了，因此這個“ubuntu每日小技巧”系列旨在幫助你和新用户輕鬆設置管理ubuntu。</p><p>Ubuntu有一個菜單欄。這個主菜單欄是在屏幕的頂端黑色條狀欄，其包含了狀態菜單或指示器和時間日期，音量鍵，應用的菜單和窗口管理按鈕。</p><p>窗口管理按鈕在主菜單（黑色條狀欄）的左上角。當年你打開一個程序的時候，主菜單左上角的按鈕包括關閉、最小化、最大化、和恢復大小按鈕，這些按鈕叫做窗口管理按鈕。</p><p>應用的菜單位於窗口管理按鈕的右側。當應用打開時才顯示應用菜單。</p><p>默認情況下，ubuntu隱藏了窗口應用菜單和管理按鈕，只有當你把鼠標放在左側角里的時候才能看到。如果你打開一個程序但是找不到菜單，只需要把你的鼠標移動到屏幕左上角就可以使它顯示出來。</p><p>如果這讓你很困惑，而且你想關閉（全局的）應用菜單而使每個程序都有自己的菜單的話，繼續向下看。</p><p>運行以下命令以安裝或刪除應用菜單：</p><pre><code>sudo apt-get autoremove indicator-appmenu
</code></pre><p>運行上面的命令將會刪除應用菜單即全局菜單。現在，為了使改變生效，先退出然後再登錄回來。</p><p>現在，當你打開一個ubuntu裏面的程序的時候，每個程序就會用顯示自己的菜單代替把它隱藏在全局菜單或主菜單裏。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/09/ubuntuappmenuglobalmenu.png" alt=""></p><p>就是這樣! 想返回原來的狀態的話,運行下面的命令：</p><pre><code>sudo apt-get install indicator-appmenu
</code></pre><p>使用愉快!</p><hr>`,16)),a("p",null,[t[1]||(t[1]=n("via: ",-1)),u(e,{href:"http://www.liberiangeek.net/2013/09/daily-ubuntu-tips-understanding-app-menus-buttons/"},{default:p(()=>[...t[0]||(t[0]=[n("http://www.liberiangeek.net/2013/09/daily-ubuntu-tips-understanding-app-menus-buttons/",-1)])]),_:1})]),a("p",null,[t[4]||(t[4]=n("本文由 ",-1)),u(e,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[2]||(t[2]=[n("LCTT",-1)])]),_:1}),t[5]||(t[5]=n(" 原創翻譯，",-1)),u(e,{href:"http://linux.cn/"},{default:p(()=>[...t[3]||(t[3]=[n("Linux中國",-1)])]),_:1}),t[6]||(t[6]=n(" 榮譽推出",-1))]),a("p",null,[t[9]||(t[9]=n("譯者：",-1)),u(e,{href:"https://github.com/crowner"},{default:p(()=>[...t[7]||(t[7]=[n("crowner",-1)])]),_:1}),t[10]||(t[10]=n(" 校對：",-1)),u(e,{href:"https://github.com/wxy"},{default:p(()=>[...t[8]||(t[8]=[n("wxy",-1)])]),_:1})])])}const x=s(l,[["render",b]]);export{_ as __pageData,x as default};
